def sha(content):
    return hashlib.sha256(content).hexdigest()


def payload():
    obj = json.loads(zlib.decompress(base64.b85decode(PAYLOAD_B85)).decode('utf-8'))
    result = {}
    for rel, choices in obj.items():
        result[rel] = {expected: zlib.decompress(base64.b85decode(value))
                       for expected, value in choices.items()}
    return result


def locate():
    current = Path.cwd().resolve()
    if current.name != BE:
        raise RuntimeError(f"REJECT: CWD must be {BE}; got {current}")
    front = current.parent / FE
    if not front.is_dir():
        raise RuntimeError(f"REJECT: missing sibling frontend: {front}")
    if Path(__file__).resolve().parent != front.resolve():
        raise RuntimeError(f"REJECT: updater must be located in frontend root {front}")
    return current.parent


def assess(root, packages):
    result = {}
    for rel, choices in packages.items():
        dest = root / rel
        if not dest.is_file():
            result[rel] = ('MISSING', None, None)
            continue
        actual = sha(dest.read_bytes())
        if actual in choices:
            result[rel] = ('PATCH_NEEDED', actual, actual)
            continue
        matching_updated = next((expected for expected, output in choices.items()
                                 if sha(output) == actual), None)
        result[rel] = ('ALREADY_APPLIED', actual, matching_updated) if matching_updated else ('UNEXPECTED', actual, None)
    return result


def main():
    p=argparse.ArgumentParser(description=__doc__)
    group=p.add_mutually_exclusive_group(required=True)
    group.add_argument('--scan',action='store_true')
    group.add_argument('--apply',action='store_true')
    group.add_argument('--verify',action='store_true')
    args=p.parse_args()
    try:
        root=locate()
        packs=payload()
        states=assess(root,packs)
        print('[IPTH MES QTY CONFIRMATION] v1.0.0 | root',root)
        for rel,(state,digest,variant) in states.items():
            print(f'[{state}] {rel} | SHA256={digest or "MISSING"}'
                  + (f' | baseline={variant}' if variant else ''))
        if any(s in {'MISSING','UNEXPECTED'} for s,_,_ in states.values()):
            print('REJECT: source unknown. Run a fresh collector if code was edited. No writes.');return 3
        if args.scan:
            print('SCAN PASS: no files written.');return 0
        if args.verify:
            if any(s!='ALREADY_APPLIED' for s,_,_ in states.values()):
                print('VERIFY FAIL: some files not updated.');return 4
            for rel in packs:
                if rel.endswith('.py'):
                    ast.parse((root/rel).read_text(encoding='utf-8'), filename=rel)
            print('VERIFY PASS: all 6 patched source hashes match and Python AST valid.');return 0
        if all(s=='ALREADY_APPLIED' for s,_,_ in states.values()):
            print('APPLY: already applied; no changes.');return 0

        stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
        backup=root/FE/f'.ipth_assy_qtymode_backup_{stamp}'
        if backup.exists():
            print('REJECT: backup path exists:',backup);return 5
        backup.mkdir(parents=True)
        to_patch={}
        receipt=[]
        try:
            # Validate every payload SHA against its expected content before writing.
            for rel,(state,digest,variant) in states.items():
                dest=root/rel
                copy=backup/rel
                copy.parent.mkdir(parents=True,exist_ok=True)
                shutil.copy2(dest,copy)
                if sha(copy.read_bytes()) != digest:
                    raise RuntimeError('Source changed while backing up: '+rel)
                if state=='PATCH_NEEDED':
                    to_patch[rel]=(digest,packs[rel][variant])
                receipt.append({'path':rel,'pre_sha256':digest,'post_sha256':
                                sha(to_patch[rel][1]) if rel in to_patch else digest})
            (backup/'receipt.json').write_text(json.dumps(receipt,indent=2),encoding='utf-8')
            changed=[]
            try:
                for rel,(expected,content) in to_patch.items():
                    dest=root/rel
                    if sha(dest.read_bytes())!=expected:
                        raise RuntimeError('Concurrent source edit: '+rel)
                    if rel.endswith('.py'):
                        ast.parse(content.decode('utf-8'),filename=rel)
                    fd,tmp=tempfile.mkstemp(prefix='.'+dest.name+'.qtymode.',dir=str(dest.parent))
                    try:
                        os.fchmod(fd,stat.S_IMODE(dest.stat().st_mode))
                        with os.fdopen(fd,'wb') as out:
                            out.write(content);out.flush();os.fsync(out.fileno())
                        os.replace(tmp,dest)
                        changed.append(rel)
                    finally:
                        if os.path.exists(tmp):os.unlink(tmp)
                newstates=assess(root,packs)
                if any(s!='ALREADY_APPLIED' for s,_,_ in newstates.values()):
                    raise RuntimeError('Post-write hash verification failed')
            except Exception:
                for rel in reversed(changed):
                    shutil.copy2(backup/rel,root/rel)
                raise
        except Exception as exc:
            print('APPLY FAILED:',exc, '| backup:',backup, file=sys.stderr)
            return 6
        print('APPLY PASS: backup at',backup)
        print('NEXT: --verify, restart Backend, rebuild/restart Frontend. NO DB changes.')
        return 0
    except Exception as exc:
        print('[ERROR]',exc, file=sys.stderr);return 2

if __name__=='__main__':
    sys.exit(main())
